import com.opencsv.CSVReader;
import java.io.FileReader;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class Importer {
    private ConcurrentMap<String, Integer> skuCounts = new ConcurrentHashMap<>();

    public void importFeed(String filePath) {
        try (CSVReader reader = new CSVReader(new FileReader(filePath))) {
            String[] line;
            int skippedRows = 0;

            while ((line = reader.readNext()) != null) {
                if (isValidLine(line)) {
                    processLine(line);
                } else {
                    skippedRows++;
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        System.out.println("Skipped rows: " + skippedRows);
    }

    private boolean isValidLine(String[] line) {
        // Implement validation logic for malformed input
        return line.length >= 4 && !line[1].isEmpty() && line[2].matches("\\d+(\\.\\d+)?");
    }

    private void processLine(String[] line) {
        // Process the line and update skuCounts
        String sku = line[0];
        skuCounts.merge(sku, 1, Integer::sum);
    }

